// Tarifa padrao R$/kWh e numero de moradores
const TARIFA_KWH = 0.92;
const NUM_MORADORES = 2;

const data = msg.payload;
if (!data || !data.node_id) return null;

// Recupera acumulado de cada comodo no contexto do fluxo
let kwhComodo1   = flow.get('kwh_comodo_1') || 0;
let kwhComodo2   = flow.get('kwh_comodo_2') || 0.150;
let kwhAreaComum = flow.get('kwh_area_comum') || 0;

if (data.node_id === 'comodo_1') {
    kwhComodo1 = Number(data.energia_kwh) || 0;
    flow.set('kwh_comodo_1', kwhComodo1);
} else if (data.node_id === 'comodo_2') {
    kwhComodo2 = Number(data.energia_kwh) || 0;
    flow.set('kwh_comodo_2', kwhComodo2);
} else if (data.node_id === 'area_comum') {
    kwhAreaComum = Number(data.energia_kwh) || 0;
    flow.set('kwh_area_comum', kwhAreaComum);
}

// Rateio da Area Comum dividido igualmente entre os moradores
const rateioComumPorMorador = kwhAreaComum / NUM_MORADORES;

const totalKwhMorador1 = kwhComodo1 + rateioComumPorMorador;
const totalKwhMorador2 = kwhComodo2 + rateioComumPorMorador;

const faturaMorador1_RS = Number((totalKwhMorador1 * TARIFA_KWH).toFixed(2));
const faturaMorador2_RS = Number((totalKwhMorador2 * TARIFA_KWH).toFixed(2));
const faturaTotal_RS    = Number((faturaMorador1_RS + faturaMorador2_RS).toFixed(2));

msg.payload = {
    ultimo_no: data.node_id,
    potencia_atual_w: data.potencia_w,
    luz_acesa: data.luz_acesa ? 'ACESA' : 'APAGADA',
    kwh_comodo_1: Number(kwhComodo1.toFixed(3)),
    kwh_comodo_2: Number(kwhComodo2.toFixed(3)),
    kwh_area_comum: Number(kwhAreaComum.toFixed(3)),
    fatura_morador_1_rs: faturaMorador1_RS,
    fatura_morador_2_rs: faturaMorador2_RS,
    fatura_total_rs: faturaTotal_RS,
    timestamp: new Date().toISOString()
};

return msg;
